def seed_initial_catalog(apps, schema_editor):
    """
    Seed inicial del catálogo, tal cual la lista citada por Miguel
    Ángel en S040 -- no cerrada, ampliable después desde el propio
    catálogo.
    """
    DocumentTypeCatalog = apps.get_model("document_explorer", "DocumentTypeCatalog")
    initial_types = [
        ("ITV", "ITV", "MACHINE"),
        ("OCA", "OCA", "MACHINE"),
        ("SEGURO", "Recibo del seguro", "BOTH"),
        ("CURSO", "Curso / formación", "PERSONAL"),
        ("DNI", "DNI", "PERSONAL"),
        ("SEG_SOCIAL", "Tarjeta de la Seguridad Social", "PERSONAL"),
        ("RECONOCIMIENTO_MEDICO", "Reconocimiento médico", "PERSONAL"),
    ]
    for code, label, domain in initial_types:
        DocumentTypeCatalog.objects.get_or_create(
            code=code,
            defaults={"label": label, "domain": domain, "is_active": True},
        )


